solution.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long dau = in.nextLong();
        long mau = in.nextLong();
        System.out.println(String.format(java.util.Locale.US, "%.1f%%", 100.0 * dau / mau));
    }
}

